//! Correlation and L/R balance of the rolling stereo-statistics window.

use shirabe_dsp::stereo::{balance_to_db, StereoStatistics, WINDOW_SECONDS};

const RATE: f32 = 48_000.0;
const TONE_HZ: f32 = 1_000.0;
const AMPLITUDE: f32 = 0.5;
/// One full window at 48 kHz (0.4 s).
const FULL: usize = 19_200;

/// A 1 kHz sine of `amplitude` at `phase` cycles, sampled at `rate`.
fn tone(index: usize, amplitude: f32, phase: f32, rate: f32) -> f32 {
    let t = index as f32 / rate;
    amplitude * (std::f32::consts::TAU * (TONE_HZ * t + phase)).sin()
}

/// Feeds `frames` samples generated by `signal` in blocks of `block` samples.
fn feed<F: Fn(usize) -> (f32, f32)>(
    stats: &mut StereoStatistics,
    frames: usize,
    block: usize,
    signal: F,
) {
    let mut left = vec![0.0f32; block.max(1)];
    let mut right = vec![0.0f32; block.max(1)];
    let mut done = 0;
    while done < frames {
        let count = block.min(frames - done);
        for (i, (l, r)) in left[..count]
            .iter_mut()
            .zip(&mut right[..count])
            .enumerate()
        {
            let (a, b) = signal(done + i);
            *l = a;
            *r = b;
        }
        stats.process(&left[..count], &right[..count]);
        done += count;
    }
}

fn in_phase(index: usize) -> (f32, f32) {
    let s = tone(index, AMPLITUDE, 0.0, RATE);
    (s, s)
}

fn correlation(stats: &StereoStatistics) -> f32 {
    stats.readout().correlation.expect("correlation available")
}

fn balance(stats: &StereoStatistics) -> f32 {
    stats.readout().balance.expect("balance available")
}

#[test]
fn a_new_meter_reports_nothing() {
    let stats = StereoStatistics::new(RATE);
    assert_eq!(stats.readout().correlation, None);
    assert_eq!(stats.readout().balance, None);
}

#[test]
fn values_are_unavailable_until_the_window_is_full() {
    let mut stats = StereoStatistics::new(RATE);
    feed(&mut stats, FULL - 1, 512, in_phase);
    assert_eq!(stats.readout().correlation, None);
    assert_eq!(stats.readout().balance, None);

    feed(&mut stats, 1, 1, |i| in_phase(FULL - 1 + i));
    assert!(stats.readout().correlation.is_some());
    assert!(stats.readout().balance.is_some());
}

#[test]
fn in_phase_stereo_reads_unity_correlation_and_equal_balance() {
    let mut stats = StereoStatistics::new(RATE);
    feed(&mut stats, FULL, 512, in_phase);
    assert!((correlation(&stats) - 1.0).abs() < 1e-6);
    assert!(balance(&stats).abs() < 1e-6);
}

#[test]
fn anti_phase_stereo_reads_minus_unity_correlation_and_equal_balance() {
    let mut stats = StereoStatistics::new(RATE);
    feed(&mut stats, FULL, 512, |i| {
        let s = tone(i, AMPLITUDE, 0.0, RATE);
        (s, -s)
    });
    assert!((correlation(&stats) + 1.0).abs() < 1e-6);
    assert!(balance(&stats).abs() < 1e-6);
}

#[test]
fn quadrature_stereo_reads_zero_correlation() {
    let mut stats = StereoStatistics::new(RATE);
    feed(&mut stats, FULL, 512, |i| {
        let s = tone(i, AMPLITUDE, 0.0, RATE);
        let c = tone(i, AMPLITUDE, 0.25, RATE);
        (s, c)
    });
    assert!(correlation(&stats).abs() < 1e-3, "{}", correlation(&stats));
    assert!(balance(&stats).abs() < 1e-3);
}

#[test]
fn balance_follows_the_channel_energies() {
    // Left at full amplitude, right at half amplitude: the right energy is a quarter of the
    // left, so the balance is (0.25 - 1) / (0.25 + 1) = -0.6.
    let mut stats = StereoStatistics::new(RATE);
    feed(&mut stats, FULL, 512, |i| {
        (tone(i, 1.0, 0.0, RATE), tone(i, 0.5, 0.0, RATE))
    });
    assert!((correlation(&stats) - 1.0).abs() < 1e-6);
    assert!((balance(&stats) + 0.6).abs() < 1e-3, "{}", balance(&stats));
}

#[test]
fn balance_ignores_phase() {
    // Anti-phase, right at half amplitude: still fully correlated, still 0.6 to the left.
    let mut stats = StereoStatistics::new(RATE);
    feed(&mut stats, FULL, 512, |i| {
        (tone(i, 1.0, 0.0, RATE), tone(i, 0.5, 0.5, RATE))
    });
    assert!((correlation(&stats) + 1.0).abs() < 1e-6);
    assert!((balance(&stats) + 0.6).abs() < 1e-3);
}

#[test]
fn a_one_sided_signal_has_a_balance_but_no_correlation() {
    let mut right_only = StereoStatistics::new(RATE);
    feed(&mut right_only, FULL, 512, |i| {
        (0.0, tone(i, AMPLITUDE, 0.0, RATE))
    });
    assert_eq!(right_only.readout().correlation, None);
    assert_eq!(balance(&right_only), 1.0);

    let mut left_only = StereoStatistics::new(RATE);
    feed(&mut left_only, FULL, 512, |i| {
        (tone(i, AMPLITUDE, 0.0, RATE), 0.0)
    });
    assert_eq!(left_only.readout().correlation, None);
    assert_eq!(balance(&left_only), -1.0);
}

#[test]
fn one_silent_channel_after_signal_still_has_no_correlation() {
    let mut stats = StereoStatistics::new(RATE);
    feed(&mut stats, FULL, 512, in_phase);
    feed(&mut stats, FULL, 512, |i| {
        (0.0, tone(FULL + i, AMPLITUDE, 0.0, RATE))
    });
    assert_eq!(stats.readout().correlation, None);
    assert_eq!(balance(&stats), 1.0);
}

#[test]
fn silence_reports_nothing() {
    let mut stats = StereoStatistics::new(RATE);
    feed(&mut stats, FULL, 512, |_| (0.0, 0.0));
    assert_eq!(stats.readout().correlation, None);
    assert_eq!(stats.readout().balance, None);
}

#[test]
fn content_below_the_silence_floor_reports_nothing() {
    let mut stats = StereoStatistics::new(RATE);
    feed(&mut stats, FULL, 512, |i| {
        let s = tone(i, 1e-7, 0.0, RATE);
        (s, s)
    });
    assert_eq!(stats.readout().correlation, None);
    assert_eq!(stats.readout().balance, None);
}

#[test]
fn a_constant_dc_offset_is_not_rejected() {
    // Documented behaviour: the cross product is taken without DC rejection, so identical
    // offsets read as perfectly correlated. Programme material normally has no DC.
    let mut stats = StereoStatistics::new(RATE);
    feed(&mut stats, FULL, 512, |_| (0.25, 0.25));
    assert!((correlation(&stats) - 1.0).abs() < 1e-6);
    assert!(balance(&stats).abs() < 1e-6);
}

#[test]
fn the_result_does_not_depend_on_the_block_partition() {
    let signal = |i: usize| {
        let l = tone(i, AMPLITUDE, 0.0, RATE);
        let r = 0.6 * tone(i, AMPLITUDE, 0.25, RATE) + 0.2 * tone(i, 0.3 * AMPLITUDE, 0.1, RATE);
        (l, r)
    };
    let mut reference = StereoStatistics::new(RATE);
    feed(&mut reference, FULL + 1234, FULL + 1234, signal);

    for block in [1, 7, 64, 441, 4096] {
        let mut stats = StereoStatistics::new(RATE);
        feed(&mut stats, FULL + 1234, block, signal);
        assert_eq!(
            stats.readout(),
            reference.readout(),
            "block size {block} changed the result"
        );
    }
}

#[test]
fn the_window_rolls_to_the_new_signal_within_one_window() {
    let mut stats = StereoStatistics::new(RATE);
    feed(&mut stats, 2 * FULL, 512, in_phase);
    assert!((correlation(&stats) - 1.0).abs() < 1e-6);

    // Half a window of anti-phase replaces half of the window: equal energies cancel.
    feed(&mut stats, FULL / 2, 512, |i| {
        let s = tone(2 * FULL + i, AMPLITUDE, 0.0, RATE);
        (s, -s)
    });
    assert!(correlation(&stats).abs() < 1e-3, "{}", correlation(&stats));

    // A whole window of anti-phase leaves nothing of the old signal.
    feed(&mut stats, FULL / 2, 512, |i| {
        let s = tone(2 * FULL + FULL / 2 + i, AMPLITUDE, 0.0, RATE);
        (s, -s)
    });
    assert!((correlation(&stats) + 1.0).abs() < 1e-6);
}

#[test]
fn the_window_is_the_same_duration_at_every_sample_rate() {
    for rate in [44_100.0f32, 48_000.0, 88_200.0, 96_000.0, 192_000.0] {
        let samples = (f64::from(rate) * WINDOW_SECONDS).round() as usize;
        let mut stats = StereoStatistics::new(rate);
        assert_eq!(stats.window_samples(), samples, "rate {rate}");
        assert!((stats.window_seconds() - WINDOW_SECONDS).abs() < 1e-9);
        assert_eq!(stats.sample_rate(), f64::from(rate));

        feed(&mut stats, samples - 1, 512, |i| {
            let s = tone(i, AMPLITUDE, 0.0, rate);
            (s, -s)
        });
        assert_eq!(stats.readout().correlation, None, "rate {rate}");
        feed(&mut stats, 1, 1, |i| {
            let s = tone(samples - 1 + i, AMPLITUDE, 0.0, rate);
            (s, -s)
        });
        assert!(
            (correlation(&stats) + 1.0).abs() < 1e-4,
            "rate {rate}: {}",
            correlation(&stats)
        );
    }
}

#[test]
fn reset_clears_the_measurement_and_needs_a_new_window() {
    let mut stats = StereoStatistics::new(RATE);
    feed(&mut stats, FULL, 512, in_phase);
    assert!(stats.readout().correlation.is_some());

    stats.reset();
    assert_eq!(stats.readout().correlation, None);
    assert_eq!(stats.readout().balance, None);
    feed(&mut stats, FULL - 1, 512, in_phase);
    assert_eq!(stats.readout().correlation, None);
    feed(&mut stats, 1, 1, |i| in_phase(FULL - 1 + i));
    assert!((correlation(&stats) - 1.0).abs() < 1e-6);
}

#[test]
fn preparing_a_new_sample_rate_restarts_the_window() {
    let mut stats = StereoStatistics::new(RATE);
    feed(&mut stats, FULL, 512, in_phase);
    assert!(stats.readout().correlation.is_some());

    stats.prepare(96_000.0);
    assert_eq!(stats.window_samples(), 38_400);
    assert_eq!(stats.readout().correlation, None);
    feed(&mut stats, 38_400, 512, |i| {
        let s = tone(i, AMPLITUDE, 0.0, 96_000.0);
        (s, s)
    });
    assert!((correlation(&stats) - 1.0).abs() < 1e-6);
}

#[test]
fn the_window_length_is_bounded() {
    // An absurd host sample rate must not allocate an unbounded ring.
    let stats = StereoStatistics::new(4_000_000.0);
    assert!(stats.window_samples() <= shirabe_dsp::stereo::MAX_WINDOW_SAMPLES);
    assert!(stats.window_samples() > 0);
}

#[test]
fn noisy_input_stays_within_the_reported_range() {
    // Two independent pseudo-random streams (xorshift, fixed seeds).
    fn noise(len: usize, mut state: u64) -> Vec<f32> {
        (0..len)
            .map(|_| {
                state ^= state << 13;
                state ^= state >> 7;
                state ^= state << 17;
                ((state >> 40) as f32 / (1u64 << 24) as f32) * 2.0 - 1.0
            })
            .collect()
    }
    let total = 4 * FULL;
    let left = noise(total, 0x2545_f491_4f6c_dd1d);
    let right = noise(total, 0x9e37_79b9_7f4a_7c15);
    let mut stats = StereoStatistics::new(RATE);
    feed(&mut stats, total, 512, |i| (left[i], right[i]));

    let c = correlation(&stats);
    let b = balance(&stats);
    assert!((-1.0..=1.0).contains(&c), "{c}");
    assert!((-1.0..=1.0).contains(&b), "{b}");
    assert!(c.abs() < 0.1, "independent noise is uncorrelated: {c}");
}

#[test]
fn balance_converts_to_decibels() {
    assert_eq!(balance_to_db(0.0), 0.0);
    assert!((balance_to_db(-0.6) + 6.0206).abs() < 1e-3);
    assert!((balance_to_db(0.6) - 6.0206).abs() < 1e-3);
    assert_eq!(balance_to_db(1.0), f32::INFINITY);
    assert_eq!(balance_to_db(-1.0), f32::NEG_INFINITY);
}
